	t.Parallel()
	now := time.Now().Local()
	today := now.Format("2006-01-02")
	yesterday := now.AddDate(0, 0, -1).Format("2006-01-02")
	older := now.AddDate(0, 0, -5).Format("2006-01-02")
	future := now.AddDate(0, 0, 2).Format("2006-01-02")

	tests := []struct {
